// CSS modules' class maps. next-env.d.ts declares these too, but it's generated by `next dev`/
// `next build` and gitignored, so a fresh checkout's typecheck needs this.
declare module "*.module.css" {
  const classes: Readonly<Record<string, string>>;
  export default classes;
}

// `import text from "./file.md?raw"`: a file's text, bundled at build time (next.config.ts adds the
// webpack rule; Vitest supports `?raw` itself).
declare module "*?raw" {
  const text: string;
  export default text;
}
